for (size_t i = start; i < end; ++i) {
    Particle& p_i = particles[i];
    glm::vec3 forcePressure(0.0f);
    glm::vec3 forceViscosity(0.0f);

    glm::ivec3 cell = getCell(&p_i, h);

    for (int x = -1; x <= 1; ++x) {
        for (int y = -1; y <= 1; ++y) {
            for (int z = -1; z <= 1; ++z) {
                uint32_t hash = getHash(cell + glm::ivec3(x, y, z));
                uint32_t particleIdx = particleTable[hash];

                while (particleIdx != NO_PARTICLE) {
                    if (particleIdx != i) {
                        Particle& p_j = particles[particleIdx];
                        glm::vec3 diff = p_i.position - p_j.position;
                        float r2 = glm::length2(diff);

                        if (r2 < h2) {
                            float r = std::sqrt(r2);
                            glm::vec3 dir = diff / (r + 1e-6f);

                            // Pressure force: -grad(P)
                            // Formula: -sum( m * (Pi + Pj)/(2*rho_j) * gradW )
                            float pressureAvg = (p_i.pressure + p_j.pressure) / (2.0f * p_j.density);
                            forcePressure -= dir * mass * pressureAvg * spikyGrad * std::pow(h - r, 2.0f);

                            // Viscosity force: mu * laplacian(v)
                            // Formula: mu * sum( m * (vj - vi)/rho_j * lapW )
                            forceViscosity += (p_j.velocity - p_i.velocity) * (viscosity * mass * (1.0f / p_j.density) * spikyLap * (h - r));
                        }
                    }
                    particleIdx = p_j.next; // Assuming Particle struct has a 'next' pointer for the linked list in the table
                }
            }
        }
    }
    p_i.force = forcePressure + forceViscosity;
}

